"""FM-16D: original reasoning pathways; proposed demand and rubrics, teacher pending."""
import sympy as s
from calibration_bank import LEVELS,L,seq
M=s.Matrix
k,h,d,C=s.symbols('k h d C',real=True)
PATHS={'det-two':'MAT.determinant.two','inverse-product':'MAT.inverse-properties.product','perpendicular-parameter':'VEC.perpendicular.parameter','triangle-area':'VEC.area-volume.triangle'}
MISTAKES={'det-two':'Adding the diagonal products, or losing one root when solving a squared parameter equation.','inverse-product':'Reversing the order of the original product incorrectly, or taking an inverse of a singular matrix.','perpendicular-parameter':'Assuming a zero vector defines a direction or dropping a parameter branch.','triangle-area':'Omitting the factor one half, using position vectors instead of displacements, or losing a branch when solving a distance equation.'}
RATIONALES={
'det-two':['Evaluate a signed arithmetic expression.','Explain how exchanging rows changes the determinant sign.','Compute a fully specified determinant.','Connect determinant multiplicativity with solving an unknown determinant.','Use a prescribed product determinant to recover both parameter branches and test invertibility.','Classify the number of parameter solutions for every real target determinant.'],
'inverse-product':['Solve a scalar inverse-operation problem.','Choose between supplied candidates by reasoning about inverse order.','Compute the inverse of a product using its factors.','Undo successive transformations to recover a vector.','Recover an unknown factor from the inverse product and another factor.','Prove exactly when the incorrect order accidentally works, including excluded singular parameters.'],
'perpendicular-parameter':['Solve a linear equation.','Explain why zero scalar product is not enough to define an angle with a zero vector.','Find an unknown by setting a scalar product to zero.','Use a point displacement and a line direction to find a perpendicular projection.','Solve simultaneous perpendicularity constraints.','Classify the number of perpendicularity solutions over a second parameter, proving completeness.'],
 'triangle-area':['Calculate the area of a right triangle.','Explain orientation independence using the cross product.','Find an area from two specified displacement vectors.','Construct displacement vectors from three points before computing area.','Recover both possible unknown coordinates from a prescribed area.','Find a global minimum and classify all parameter solutions for any target area.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown pathway cell')
 a=v+1;b=a+1
 if path=='det-two':
  A=M([[a,1],[2,b]]);det=a*b-2
  if l==1:
   q=f'Evaluate ${a}\\times {b}-2$.';f=[det];ans=L(det);steps=[f'Multiply first to obtain {a*b}, then subtract 2 to obtain {det}.'];hints=['Multiply before subtracting.','The subtraction is the final operation.']
  elif l==2:
   q=f'The rows of {L(A)} are exchanged. A learner claims the determinant does not change. Calculate both determinants and explain.';f=[det,-det];ans=f'Original {det}; after swap {-det}.';steps=[f'The original diagonal difference is ${a}\\cdot{b}-2={det}$.',f'After exchanging rows, it is $2-{a}\\cdot{b}={-det}$.','Exchanging the two rows reverses the sign; the determinant is alternating.'];hints=['Write the swapped matrix.','Compare the two diagonal differences.']
  elif l==3:
   B=M([[a,-2],[3,b]]);f=[a*b+6];q=f'Calculate the signed determinant of {L(B)}.';ans=L(f[0]);steps=[f'The main-diagonal product is {a*b} and the other product is -6.',f'Subtraction gives ${a*b}-(-6)={f[0]}$.'];hints=['Keep the negative sign in the off-diagonal product.','Use main diagonal minus other diagonal.']
  elif l==4:
   B=M([[2,1],[0,a]]);P=A*B;f=[P.det(),A.det()];q=f'Matrices A and B satisfy $AB={s.latex(P)}$ and $B={s.latex(B)}$. Calculate $\\det(AB)$ and use it to find $\\det A$ without recovering A.';ans=seq(*f);steps=[f'The two diagonal products of AB give determinant {P.det()}.',f'The triangular B has determinant {2*a}, which is nonzero.',f'Use $\\det(AB)=\\det A\\det B$ to obtain $\\det A={P.det()}/{2*a}={det}$.'];hints=['Calculate the two given determinants.','Divide by the nonzero determinant of B.']
  elif l==5:
   B=M([[k,a],[b,k]]);E=s.diag(a,1);target=-a*a;f=[-a,a,True];q=f'Let $B={s.latex(B)}$ and $E={s.latex(E)}$. The signed determinant of BE is {target}. Determine every real k and decide whether B is invertible in each case.';ans=f'$k=\\pm {a}$; B is invertible for both.';steps=[f'The determinant of E is {a}, and that of B is $k^2-{a*b}$.',f'Using determinant multiplicativity gives ${a}(k^2-{a*b})=-{a*a}$, hence $k^2={a*a}$.',f'Both distinct roots $k=\\pm {a}$ satisfy the original signed determinant equation.',f'In either case the determinant of B is {-a}, which is nonzero, so B is invertible. No other real roots exist.'];hints=['Use the determinant of a product before expanding any matrix product.','Keep both signs when solving for k; then check the determinant of B.']
  else:
   B=M([[k,a],[a,k]]);f=[k*k-a*a,-a*a,0,1,2];q=f'For every real target d, classify how many real values of k satisfy $\\det {s.latex(B)}=d$. Find all such values, including the boundary case, and justify completeness.';ans=f'$d<-{a*a}$: none; $d=-{a*a}$: k=0; $d>-{a*a}$: $k=\\pm\\sqrt{{d+{a*a}}}$.';steps=[f'The determinant is $k^2-{a*a}$, so the target equation is $k^2=d+{a*a}$.',f'If $d<-{a*a}$, the right side is negative, impossible for a real square.',f'If $d=-{a*a}$, only k=0 works.',f'If $d>-{a*a}$, the right side is positive and both distinct square roots satisfy the equation.','These three disjoint cases exhaust all real d; substituting each root into the determinant verifies it.'];hints=['Express the determinant as a quadratic in k.','Classify the sign of the right side after isolating the square.']
 elif path=='inverse-product':
  A=M([[1,a],[0,1]]);B=s.diag(b,1);P=A*B;u=M([1,2]);w=P*u
  if l==1:
   q=f'A nonzero number x is multiplied by {a} then {b} to produce {2*a*b}. Undo these operations to find x.';f=[2];ans=L(2);steps=[f'Divide by the last multiplier {b} to get {2*a}.',f'Then divide by {a} to get 2.'];hints=['Undo the last operation first.','Both multipliers are nonzero.']
  elif l==2:
   good=B.inv()*A.inv();bad=A.inv()*B.inv();f=[good,bad];q=f'For $A={s.latex(A)}$ and $B={s.latex(B)}$, two candidates for $(AB)^{{-1}}$ are {L(good)} and {L(bad)}. The second is $A^{{-1}}B^{{-1}}$. Which is correct? Explain using the order of undoing transformations.';ans=f'Correct {L(good)}; incorrect {L(bad)}.';steps=[f'The product AB is {L(P)}; its inverse is {L(good)}.',f'Multiplying the inverses in the original order gives {L(bad)} instead.','They differ in their upper-right entries. Inversion reverses the order because the last transformation must be undone first.'];hints=['Compute each inverse separately.','Compare the off-diagonal entries of the two products.']
  elif l==3:
   f=[B.inv()*A.inv()];q=f'Use the inverse-product rule to find $(AB)^{{-1}}$ when $A={s.latex(A)}$, $B={s.latex(B)}$.';ans=L(f[0]);steps=[f'The inverses of A and B are {L(A.inv())} and {L(B.inv())}.',f'Multiply in reverse order to obtain {L(f[0])}.'];hints=['The inverse of a shear has the opposite shear parameter.','Put the inverse of B on the left.']
  elif l==4:
   mid=A.inv()*w;f=[mid,u];q=f'A vector p undergoes B then A, where $A={s.latex(A)}$ and $B={s.latex(B)}$. The final vector is {L(w)}. Recover the intermediate vector and p.';ans=f'Intermediate {L(mid)}; p={L(u)}.';steps=[f'Undo A by multiplying the final vector by {L(A.inv())}, giving {L(mid)}.',f'Undo B using {L(B.inv())}, giving {L(u)}.',f'Check forward: B maps this vector to {L(mid)} and A then gives {L(w)}.'];hints=['The given final vector is ABp.','Undo A before undoing B.']
  elif l==5:
   E=P.inv();f=[A];q=f'An unknown invertible A satisfies $(AB)^{{-1}}={s.latex(E)}$, where $B={s.latex(B)}$. Recover A and verify the original equation.';ans=L(A);steps=[f'Invert the given matrix to obtain $AB={s.latex(P)}$.',f'Right-multiply by $B^{{-1}}={s.latex(B.inv())}$ to isolate A, giving {L(A)}.',f'The recovered product has inverse {L(E)}, as required.'];hints=['Invert both sides first.','Multiply on the correct side of the equation.']
  else:
   U=M([[1,k],[0,1]]);D=s.diag(h,b);f=[k*(h-b),b];q=f'Let $A={s.latex(U)}$ and $B={s.latex(D)}$. For all real k,h, determine when both inverses exist and when $(AB)^{{-1}}=A^{{-1}}B^{{-1}}$ actually holds. Prove your classification.';ans=f'$h\\ne0$ and either k=0 or h={b}. For h=0 the inverse equality is undefined.';steps=[f'A has determinant 1 and B determinant ${b}h$, so both are invertible exactly when h is nonzero.','For invertible matrices, the proposed equality holds exactly when $AB=BA$, by inverting both sides and using the reverse-order rule.',f'The upper-right entries of AB and BA are ${b}k$ and hk; all other entries agree.',f'Thus equality requires $k(h-{b})=0$, giving k=0 or h={b}.', 'These cases are sufficient by substitution, and h=0 must remain excluded.'];hints=['Check invertibility before manipulating inverse expressions.','Invert the proposed equality to reduce it to commutation.']
 elif path=='perpendicular-parameter':
  if l==1:
   q=f'Solve $2k+{a*b}-1=0$.';f=[s.Rational(1-a*b,2)];ans=L(f[0]);steps=[f'Move the constant to give $2k={1-a*b}$.',f'Divide by 2 to obtain {L(f[0])}.'];hints=['Subtract the constant.','Divide both sides by two.']
  elif l==2:
   q=f'At k={a}, a student claims the vector $(k-{a},0,0)$ makes a right angle with $(1,{b},0)$ because their scalar product is zero. Is the angle defined? Explain.';f=[0,False];ans='Scalar product zero; angle undefined.';steps=[f'At k={a} the first vector is the zero vector.', 'Its scalar product with every vector is zero, but its magnitude is zero.','The angle formula would divide by zero, and the zero vector has no direction, so no angle is defined.'];hints=['Substitute the parameter first.','Check both vector magnitudes before finding an angle.']
  elif l==3:
   root=s.Rational(1-a*b,2);f=[root];q=f'Find k such that the nonzero vectors $(k,{a},1)$ and $(2,{b},-1)$ are perpendicular.';ans=f'$k={s.latex(root)}$';steps=[f'Their scalar product is $2k+{a*b}-1$.',f'Equating this to zero yields $k={s.latex(root)}$.','The vectors are nonzero for every k because of their fixed nonzero components.'];hints=['Multiply corresponding components and add.','Set the scalar product to zero.']
  elif l==4:
   root=a-2*b+1;f=[root];q=f'A line passes through $Q=({a},0,1)$ with direction $(1,{b},1)$. Find k such that the segment joining Q to $P=(k,2,0)$ is perpendicular to the line, and verify.';ans=f'$k={root}$';steps=[f'The displacement from Q to P is $(k-{a},2,-1)$.',f'Its dot product with the direction is $k-{a}+{2*b}-1$.',f'Set this equal to zero to get $k={root}$. Substitution makes the dot product zero and the displacement is nonzero.'];hints=['Subtract Q from P to obtain a displacement, not a position vector.','Use the scalar product with the line direction.']
  elif l==5:
   f=[a*b,-b];q=f'Find every pair (k,h) for which $(k,h,1)$ is perpendicular to both $(1,{a},0)$ and $(0,1,{b})$. Explain why the resulting vector is nonzero.';ans=f'$k={a*b},h=-{b}$';steps=[f'The two dot-product conditions are $k+{a}h=0$ and $h+{b}=0$.',f'The second fixes $h=-{b}$ and the first then fixes $k={a*b}$.','The resulting vector has third component 1, so it is nonzero. Both independent equations have been satisfied, giving a unique pair.'];hints=['Write two separate scalar-product equations.','Solve the second equation first.']
  else:
   f=[k*k-a*a+h,a*a,0,1,2];q=f'For every real h, classify the number of real k for which $(k,{a},1)$ and $(k,-{a},h)$ are perpendicular. Give all solutions and prove they are valid.';ans=f'$h>{a*a}$: none; $h={a*a}$: k=0; $h<{a*a}$: $k=\\pm\\sqrt{{{a*a}-h}}$.';steps=[f'The dot product is $k^2-{a*a}+h$. Both vectors are nonzero because their second components are nonzero.',f'Perpendicularity is exactly $k^2={a*a}-h$.',f'If h exceeds {a*a}, the right side is negative and no real k exists.',f'At h={a*a}, only k=0 works. Below this value there are two distinct real square roots.', 'Each root satisfies the original dot product and the vectors remain nonzero. The three cases exhaust all h.'];hints=['Check that both vectors always define directions.','Classify the sign of the required squared parameter.']
 elif path=='triangle-area':
  area=s.Rational(a*b,2)
  if l==1:
   q=f'Find the area of a right-angled triangle with perpendicular sides {a} and {b}.';f=[area];ans=L(area);steps=[f'Half the product of the perpendicular side lengths is ${a*b}/2={s.latex(area)}$.'];hints=['Use half the base times perpendicular height.','Both lengths are positive.']
  elif l==2:
   u=M([a,0,0]);w=M([0,b,0]);f=[u.cross(w),w.cross(u),area];q=f'A triangle has two side vectors {L(u)} and {L(w)} from the same vertex. The first cross product is given as {L(f[0])}. A student claims reversing its order makes the triangle area negative. Explain by inferring the reverse cross product and the area.';ans=f'{L(f[0])} and {L(f[1])}; area {L(area)} in either order.';steps=[f'The first cross product is {L(f[0])}; reversing the order gives {L(f[1])}.',f'Both norms equal {a*b}, because a sign change does not change magnitude.',f'The triangle has half the parallelogram area, so both orders give {L(area)}.'];hints=['The vector product is anti-commutative.','Area uses the magnitude, not a signed component.']
  elif l==3:
   u=M([a,0,0]);w=M([0,b,1]);n=u.cross(w);f=[n,n.norm()/2];q=f'Find the exact triangle area when two sides from one vertex are {L(u)} and {L(w)}.';ans=L(f[1]);steps=[f'The cross product is {L(n)}.',f'Half its magnitude is {L(f[1])}, the triangle area.'];hints=['Compute the cross product.','Take half its Euclidean norm.']
  elif l==4:
   p=M([1,2,3]);u=M([a,1,0]);w=M([0,b,1]);n=u.cross(w);f=[u,w,n,n.norm()/2];q=f'Find the exact area of the triangle with vertices {L(p)}, {L(p+u)} and {L(p+w)}.';ans=L(f[-1]);steps=[f'Subtract the first vertex from the other two to obtain side vectors {L(u)} and {L(w)}.',f'The cross product is {L(n)}.',f'Its magnitude divided by two gives area {L(f[-1])}.'];hints=['Use displacements from a shared vertex.','The cross-product magnitude gives the parallelogram area.']
  elif l==5:
   target=a*s.sqrt(b*b+a*a)/2;f=[-a,a];q=f'A triangle with vertices $(0,0,0)$, $({a},0,0)$ and $(k,{b},k)$ has area {L(target)}. Determine every real k and check that both resulting triangles are nondegenerate.';ans=f'$k=\\pm {a}$';steps=[f'The cross product of the two side vectors is $(0,-{a}k,{a*b})$.',f'The area is ${a}\\sqrt{{k^2+{b*b}}}/2$. Equating to the given area and squaring gives $k^2={a*a}$.',f'Both signs satisfy the original positive area equation. The fixed nonzero y component {b} ensures the three vertices are not collinear.'];hints=['Express the area as a function of k.','Retain both square roots and check against the unsquared equality.']
  else:
   mn=a*b*s.sqrt(2)/4;disc=8*C*C/(a*a)-b*b;f=[mn,s.Rational(b,2),disc,0,1,2];q=f'Let the vertices be $(0,0,0)$, $({a},0,0)$ and $(k,k-{b},k)$. For every desired area $C\\geq0$, determine the number of real k and give every solution. Prove the minimum area and the boundary case.';ans=f'Minimum {L(mn)} at $k={s.latex(s.Rational(b,2))}$. Below it: none; at it: one; above it: $k=({b}\\pm\\sqrt{{8C^2/{a*a}-{b*b}}})/2$.';steps=[f'The cross product is $(0,-{a}k,{a}(k-{b}))$, so the squared area is $({a*a}/4)[k^2+(k-{b})^2]$.',f'Complete the square: the bracket is $2(k-{s.latex(s.Rational(b,2))})^2+{s.latex(s.Rational(b*b,2))}$.',f'The minimum area is {L(mn)}, attained only at $k={s.latex(s.Rational(b,2))}$. It is positive, so every triangle is nondegenerate.',f'Equating squared area to $C^2$ gives $k=({b}\\pm\\sqrt{{8C^2/{a*a}-{b*b}}})/2$ when the radicand is nonnegative.','Below the minimum no real roots exist, at the minimum the roots coincide, and above it there are two distinct roots. Since C is nonnegative, squaring introduces no extraneous area solutions.'];hints=['Compute the squared area rather than expanding a square root.','Complete the square and classify the discriminant.']
 else:raise AssertionError(path)
 def encode(w):
  if isinstance(w,bool):return w
  if isinstance(w,s.MatrixBase):return {'matrix':[[str(e) for e in row] for row in w.tolist()]}
  return str(w)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hints,rubric=[dict(marks=1,criterion=p) for p in steps],facts=[encode(e) for e in f],likely_mistake=MISTAKES[path],origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
